const $=id=>document.getElementById(id),canvas=$('preview'),ctx=canvas.getContext('2d');
let layout=null,images={},ready=false;
const esc=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function wrap(text,maxWidth){const out=[];let line='';for(const original of text.split(/\s+/).filter(Boolean)){let words=[original];if(ctx.measureText(original).width>maxWidth){words=[];let part='';for(const ch of original){if(part&&ctx.measureText(part+ch).width>maxWidth){words.push(part);part=ch}else part+=ch}if(part)words.push(part)}for(const word of words){const trial=line?line+' '+word:word;if(line&&ctx.measureText(trial).width>maxWidth){out.push(line);line=word}else line=trial}}if(line)out.push(line);return out}
function draw(){if(!ready)return;const [w,h]=$('format').value.split(',').map(Number),p=BRAND.palettes.find(x=>x.id===$('palette').value),[paper,ink,surface,accent]=p.colors;canvas.width=w;canvas.height=h;const margin=w*.075,contentW=w-2*margin,logoW=w*.30,logoH=logoW*560/2400;ctx.fillStyle=paper;ctx.fillRect(0,0,w,h);ctx.drawImage(images[p.id],margin-w*.014,h*.075,logoW,logoH);ctx.fillStyle=ink;const headline=$('headline').value.trim()||'Your next research note.';let fontSize=w*.082,lines=[],lineHeight;do{ctx.font=`500 ${fontSize}px Newsreader`;lines=wrap(headline,contentW);lineHeight=fontSize*1.1;if(lines.length*lineHeight<=h*.46)break;fontSize-=2}while(fontSize>24);const titleTop=h*.30,baseline=titleTop+fontSize*.78;ctx.fillStyle=ink;lines.forEach((line,i)=>ctx.fillText(line,margin,baseline+i*lineHeight));let deckSize=w*.0185;ctx.font=`400 ${deckSize}px Inter`;let deckLines=wrap($('deck').value.trim(),contentW);if(deckLines.length>2){deckSize*=.8;ctx.font=`400 ${deckSize}px Inter`;deckLines=wrap($('deck').value.trim(),contentW)}const deckY=Math.max(h*.77,baseline+(lines.length-1)*lineHeight+fontSize*.9);deckLines.slice(0,2).forEach((line,i)=>ctx.fillText(line,margin,deckY+i*deckSize*1.5));ctx.fillStyle=surface;ctx.fillRect(margin,h*.89,contentW,2);ctx.fillStyle=accent;ctx.fillRect(w-margin-30,h*.89-2,30,6);ctx.fillStyle=ink;ctx.font=`400 ${w*.0135}px Inter`;ctx.fillText('chipstrat.com',margin,h*.945);layout={w,h,p,margin,contentW,logoW,logoH,fontSize,lines,lineHeight,baseline,deckSize,deckLines:deckLines.slice(0,2),deckY};$('status').textContent=`Ready · ${w} × ${h} px`;}
function save(blob,ext){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`chipstrat-cover-${layout.p.id}-${layout.w}x${layout.h}.${ext}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent=`${ext.toUpperCase()} export downloaded.`;}
$('png').onclick=()=>{draw();canvas.toBlob(blob=>blob?save(blob,'png'):$('status').textContent='Export failed. Please try again.','image/png');};
$('svg').onclick=()=>{draw();const L=layout,[paper,ink,surface,accent]=L.p.colors,fonts=`@font-face{font-family:Inter;src:url(data:font/woff2;base64,${BRAND.fonts.inter}) format('woff2');font-weight:100 900;}@font-face{font-family:Newsreader;src:url(data:font/woff2;base64,${BRAND.fonts.newsreader}) format('woff2');font-weight:100 900;}`;const logo=BRAND.logos[L.p.id].replace('<svg ',`<svg x="${L.margin-L.w*.014}" y="${L.h*.075}" `).replace('width="2400"',`width="${L.logoW}"`).replace('height="560"',`height="${L.logoH}"`);const s=`<svg xmlns="http://www.w3.org/2000/svg" width="${L.w}" height="${L.h}" viewBox="0 0 ${L.w} ${L.h}" role="img" aria-label="${esc($('headline').value)}"><title>${esc($('headline').value)}</title><defs><style>${fonts}</style></defs><rect width="${L.w}" height="${L.h}" fill="${paper}"/>${logo}<g fill="${ink}" font-family="Newsreader" font-weight="500" font-size="${L.fontSize}">${L.lines.map((line,i)=>`<text x="${L.margin}" y="${L.baseline+i*L.lineHeight}">${esc(line)}</text>`).join('')}</g><g fill="${ink}" font-family="Inter" font-size="${L.deckSize}">${L.deckLines.map((line,i)=>`<text x="${L.margin}" y="${L.deckY+i*L.deckSize*1.5}">${esc(line)}</text>`).join('')}</g><rect x="${L.margin}" y="${L.h*.89}" width="${L.contentW}" height="2" fill="${surface}"/><rect x="${L.w-L.margin-30}" y="${L.h*.89-2}" width="30" height="6" fill="${accent}"/><text x="${L.margin}" y="${L.h*.945}" font-family="Inter" font-size="${L.w*.0135}" fill="${ink}">chipstrat.com</text></svg>`;save(new Blob([s],{type:'image/svg+xml'}),'svg');};
for(const id of ['headline','deck','format','palette'])$(id).addEventListener(id==='headline'||id==='deck'?'input':'change',draw);
(async()=>{try{const loads=Object.entries(BRAND.fonts).map(async([key,data])=>{const f=new FontFace(key==='inter'?'Inter':'Newsreader',`url(data:font/woff2;base64,${data})`,{weight:'100 900'});await f.load();document.fonts.add(f)});await Promise.all(loads);await Promise.all(BRAND.palettes.map(p=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[p.id]=im;resolve()};im.onerror=reject;im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(BRAND.logos[p.id])})));ready=true;draw();$('png').disabled=$('svg').disabled=false;}catch(e){$('status').textContent='Fonts could not load. Open this page in a current browser and try again.';console.error(e)}})();
